<script setup>
import {ref,onMounted} from 'vue'
import {request} from './client'
import ActionNotice from './ActionNotice.vue'
const emit=defineEmits(['navigate']),data=ref(null),busy=ref(false),error=ref('')
const labels={student_memberships:'Active student memberships',teachers:'Verified teachers',institutes:'Verified institutes',pending_profiles:'Provider reviews pending',pending_payouts:'Payout requests pending'}
async function load(){if(busy.value)return;busy.value=true;error.value='';try{data.value=await request('owner_operations','overview',{},'GET')}catch(e){error.value=e.message;data.value=null}finally{busy.value=false}}
onMounted(load)
</script>
<template><section><ActionNotice :message="error" :failure="true"/><header><div><h2>Your platform at a glance</h2><p>Live records from the connected campuses and hosted-institute registry.</p></div><button class="button subtle" :disabled="busy" @click="load">{{busy?'Loading…':'Refresh overview'}}</button></header><p v-if="error" role="alert">{{error}}</p><template v-if="data"><div class="metrics"><article class="panel"><span>Registered hosted institutes</span><strong>{{data.hosted_institutes}}</strong><button class="button subtle" @click="emit('navigate','Organizations')">Manage institutes</button></article><article class="panel"><span>Website setups needing attention</span><strong>{{data.setup_pending}}</strong><button class="button subtle" @click="emit('navigate','Provisioning')">View setup requests</button></article></div><article v-for="campus in data.campuses" :key="campus.site" class="panel campus"><h3>{{campus.site}}</h3><p v-if="!campus.available" role="status">{{campus.message}}</p><template v-else><div class="metrics"><div v-for="(value,key) in campus.counts" :key="key"><span>{{labels[key]}}</span><strong>{{value}}</strong></div></div><p>Student memberships count campus membership records, not unique people across campuses.</p><a class="button subtle" :href="campus.url" target="_blank" rel="noopener">Open campus administration ↗</a><p class="hint">Provider approvals, subscription administration, payouts and signup/privacy controls run on that campus. Sign in with an owner account authorized there; opening this link does not grant access.</p></template></article><p v-if="!data.campuses.length">No campus reporting connections configured.</p></template><div class="actions"><button v-for="item in [{name:'Plans',text:'Edit shared subscription plans'},{name:'Billing',text:'Review provider invoices'},{name:'Admin access',text:'Manage owner access'},{name:'Readiness',text:'Check service and email status'}]" :key="item.name" class="button subtle" @click="emit('navigate',item.name)">{{item.text}}</button></div></section></template>
<style scoped>header{display:flex;justify-content:space-between;align-items:start;gap:20px}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:20px}.metrics article,.campus{padding:24px}.metrics strong{display:block;font-size:30px;margin:8px 0 16px}.metrics span,.hint{font-size:13px;color:var(--muted,#71667d)}.actions{display:flex;flex-wrap:wrap;gap:12px;margin:24px 0}.campus h3{overflow-wrap:anywhere}.campus a{display:inline-block;text-decoration:none}@media(max-width:650px){header{flex-direction:column}}</style>
